import pandas as pd
import plotly.express as px
import streamlit as st

from src.database import load_experiments, save_experiment
from src.evaluator import detect_fault, evaluate_configuration
from src.simulator import FAULT_TYPES, simulate_machine

st.set_page_config(
    page_title="SensorScout",
    page_icon="🔍",
    layout="wide",
)

st.title("SensorScout")
st.caption(
    "Explore simulated machine faults and compare sensor layouts. "
    "These readings are generated by a simplified simulator."
)

# Sidebar controls
with st.sidebar:
    st.header("Simulation settings")

    fault_type = st.selectbox(
        "Fault type",
        FAULT_TYPES,
    )

    fault_position = st.slider(
        "Fault location",
        min_value=0,
        max_value=7,
        value=3,
    )

    sensor_positions = st.multiselect(
        "Sensor locations",
        options=list(range(8)),
        default=[0, 3, 6],
    )

    seed = st.number_input(
        "Random seed",
        min_value=0,
        value=42,
        step=1,
    )

    sampling_rate = st.selectbox(
        "Sampling rate per sensor (Hz)",
        options=[5, 10, 20],
        index=1,
    )

# Generate signals at a common underlying rate.
readings = simulate_machine(
    fault_type=fault_type,
    fault_position=fault_position,
    sampling_rate_hz=20,
    seed=int(seed),
)

if not sensor_positions:
    st.info("Select at least one sensor location in the sidebar.")
    st.stop()

# Display and detect using the selected sampling rate.
sampled_frames = []

for position in sensor_positions:
    sensor_readings = readings[
        readings["position"] == position
    ]

    step = 20 // sampling_rate
    sampled_frames.append(sensor_readings.iloc[::step])

visible = pd.concat(sampled_frames, ignore_index=True)
visible["sensor"] = "Position " + visible["position"].astype(str)

# Fault detection
st.subheader("Fault detection")

result = detect_fault(visible, sensor_positions)

if result["fault_detected"]:
    st.error("Fault detected in the selected sensors' readings.")
    st.write(
        f"First alarm: {result['first_alarm_s']:.1f} seconds"
    )
else:
    st.success("No fault detected in the selected sensors' readings.")

st.caption(
    "Demo alarm thresholds: vibration above 1.5 mm/s "
    "or temperature above 45°C. "
    "No alarm does not guarantee the machine is healthy."
)

# Signal metrics
left, right = st.columns(2)

with left:
    st.metric(
        "Maximum displayed vibration",
        f"{visible['vibration_rms_mm_s'].max():.2f} mm/s",
    )

with right:
    st.metric(
        "Maximum displayed temperature",
        f"{visible['temperature_c'].max():.1f} °C",
    )

# Signal charts
vibration_chart = px.line(
    visible,
    x="time_s",
    y="vibration_rms_mm_s",
    color="sensor",
    title="Vibration readings",
    labels={
        "time_s": "Time (s)",
        "vibration_rms_mm_s": "Vibration RMS (mm/s)",
        "sensor": "Sensor",
    },
)

temperature_chart = px.line(
    visible,
    x="time_s",
    y="temperature_c",
    color="sensor",
    title="Temperature readings",
    labels={
        "time_s": "Time (s)",
        "temperature_c": "Temperature (°C)",
        "sensor": "Sensor",
    },
)

if fault_type != "healthy":
    for chart in (vibration_chart, temperature_chart):
        chart.add_vline(
            x=40,
            line_dash="dash",
            annotation_text="Fault begins",
        )

st.plotly_chart(vibration_chart, width="stretch")
st.plotly_chart(temperature_chart, width="stretch")

with st.expander("View simulated readings"):
    st.dataframe(visible, width="stretch")

st.download_button(
    label="Download displayed readings as CSV",
    data=visible.to_csv(index=False),
    file_name=f"sensorscout_{fault_type}.csv",
    mime="text/csv",
)

# Configuration evaluation
st.divider()
st.subheader("Evaluate sensor layout")

st.write(
    "Test the selected sensor locations and sampling rate against "
    "24 faulty scenarios and 8 healthy scenarios."
)

st.caption(
    "This evaluation covers all fault types and locations, "
    "regardless of the fault selected for the charts."
)

config = {
    "sensor_positions": sensor_positions,
    "sampling_rates_hz": [
        sampling_rate for _ in sensor_positions
    ],
}

# Identify which settings produced the displayed result.
evaluation_key = (
    tuple(sensor_positions),
    sampling_rate,
    int(seed),
    "validation",
)

if st.button("Evaluate sensor layout"):
    with st.spinner("Testing sensor layout..."):
        evaluation = evaluate_configuration(
            config,
            scenario_set="validation",
            seed=int(seed),
        )

    st.session_state["evaluation"] = evaluation
    st.session_state["evaluation_key"] = evaluation_key
    st.session_state["saved_experiment_id"] = None

    try:
        experiment_id = save_experiment(evaluation)
        st.session_state["saved_experiment_id"] = experiment_id
    except (OSError, ValueError, TypeError) as error:
        st.error(
            f"Evaluation completed, but saving failed: {error}"
        )

# Keep the most recent result visible across normal interactions.
evaluation = st.session_state.get("evaluation")

if evaluation is not None:
    if st.session_state.get("evaluation_key") != evaluation_key:
        st.warning(
            "These results belong to your previous settings. "
            "Click Evaluate sensor layout to update them."
        )

    saved_id = st.session_state.get("saved_experiment_id")

    if saved_id:
        st.success(f"Experiment saved: {saved_id}")

    st.write("Evaluated configuration:", evaluation["config"])
    st.caption(
        f"Scenario set: {evaluation['scenario_set']} · "
        f"Seed: {evaluation['seed']}"
    )

    col1, col2, col3 = st.columns(3)

    col1.metric(
        "Fault recall",
        f"{evaluation['fault_recall']:.1%}",
    )

    precision = evaluation["precision"]

    col2.metric(
        "Precision",
        f"{precision:.1%}" if precision is not None else "N/A",
    )

    col3.metric(
        "False-alarm rate",
        f"{evaluation['false_alarm_rate']:.1%}",
    )

    col4, col5, col6 = st.columns(3)

    delay = evaluation["mean_detection_delay_s"]

    col4.metric(
        "Mean detection delay",
        f"{delay:.1f} s" if delay is not None else "N/A",
    )

    col5.metric(
        "Illustrative cost units",
        f"{evaluation['sensor_cost_units']:.0f}",
    )

    col6.metric(
        "Score",
        f"{evaluation['score']:.2f}",
    )

    st.write(
        f"Faults detected: {evaluation['faults_detected']} · "
        f"Faults missed: {evaluation['faults_missed']} · "
        f"False-alarm windows: "
        f"{evaluation['false_alarm_windows']}"
    )

    st.caption(
        "Detection delay includes detected faults only. "
        "The current score balances recall, false alarms, and cost; "
        "it does not include detection delay."
    )

    with st.expander("View individual scenario results"):
        st.dataframe(
            pd.DataFrame(evaluation["scenario_results"]),
            width="stretch",
        )


# -------------------------------------------------
# AI OPTIMIZATION DASHBOARD
# -------------------------------------------------

st.divider()
st.header("AI Sensor Optimization")
st.write(
    "SensorScout uses AI-guided experiments to discover "
    "better sensor layouts and evaluate them against "
    "simulated machine faults."
)

from src.optimizer import run_optimization, BASELINE

rounds = st.slider(
    "Number of optimization rounds",
    min_value=1,
    max_value=15,
    value=5,
    key="optimization_rounds",
)

import json
from pathlib import Path

if st.button("Load Previous Optimization"):
    results_path = Path("data/mock_run.json")

    if results_path.exists():
        with results_path.open() as f:
            st.session_state["optimization_result"] = json.load(f)
        st.success("Previous optimization results loaded!")
    else:
        st.warning("No saved optimization results found.")

if st.button("Run AI Optimization", type="primary"):
    with st.spinner(
        "DeepSeek is proposing sensor configurations "
        "and the simulator is testing them..."
    ):
        try:
            optimization_result = run_optimization(
                rounds=rounds,
                seed=int(seed),
            )
            st.session_state["optimization_result"] = (
                optimization_result
            )
        except Exception as error:
            st.error(f"Optimization failed: {error}")

optimization_result = st.session_state.get(
    "optimization_result"
)

if optimization_result is not None:

    history = optimization_result["history"]
    baseline_metrics = history[0]["metrics"]
    best_metrics = optimization_result["best_metrics"]

    baseline_score = baseline_metrics["score"]
    best_score = best_metrics["score"]

    improvement = best_score - baseline_score

    st.subheader("Optimization Results")

    col1, col2, col3, col4 = st.columns(4)

    col1.metric(
        "Baseline Score",
        f"{baseline_score:.2f}",
    )

    col2.metric(
        "Best Score",
        f"{best_score:.2f}",
        delta=f"{improvement:+.2f}",
    )

    col3.metric(
        "Fault Recall",
        f"{best_metrics['fault_recall']:.1%}",
    )

    col4.metric(
        "Sensor Cost",
        f"{best_metrics['sensor_cost_units']:.0f}",
        delta=(
            f"{best_metrics['sensor_cost_units'] - baseline_metrics['sensor_cost_units']:+.0f}"
        ),
        delta_color="inverse",
    )

    left, right = st.columns(2)

    with left:
        st.subheader("Original Configuration")
        st.write(BASELINE)

    with right:
        st.subheader("Best Configuration")
        st.write(optimization_result["best_config"])

    st.subheader("Optimization Progress")

    progress_data = pd.DataFrame([
        {
            "Round": item["round"],
            "Candidate Score": item["metrics"]["score"],
            "Best Score": item["best_score"],
        }
        for item in history
    ])

    st.line_chart(
        progress_data.set_index("Round")[
            ["Candidate Score", "Best Score"]
        ]
    )

    st.subheader("Agent Experiment History")

    experiment_rows = []

    for item in history:
        experiment_rows.append({
            "Round": item["round"],
            "Sensor Positions": str(
                item["config"]["sensor_positions"]
            ),
            "Sampling Rates": str(
                item["config"]["sampling_rates_hz"]
            ),
            "Proposal Source": item.get(
                "proposal_source", "unknown"
            ),
            "Score": round(
                item["metrics"]["score"], 2
            ),
            "Accepted": item["accepted"],
        })

    st.dataframe(
        pd.DataFrame(experiment_rows),
        width="stretch",
        hide_index=True,
    )

    st.subheader("Best Configuration Performance")

    metric1, metric2, metric3 = st.columns(3)

    metric1.metric(
        "Precision",
        f"{best_metrics['precision']:.1%}"
        if best_metrics["precision"] is not None
        else "N/A",
    )

    metric2.metric(
        "False Alarm Rate",
        f"{best_metrics['false_alarm_rate']:.1%}",
    )

    delay = best_metrics["mean_detection_delay_s"]

    metric3.metric(
        "Mean Detection Delay",
        f"{delay:.2f} seconds"
        if delay is not None
        else "N/A",
    )

    st.caption(
        "Results are based on a simplified industrial "
        "fault simulator, not real factory measurements. "
        "DeepSeek generates candidate proposals; repeated "
        "proposals may be replaced by random exploration."
    )

    st.download_button(
        "Download Optimization History",
        data=pd.DataFrame(
            experiment_rows
        ).to_csv(index=False),
        file_name="sensorscout_optimization.csv",
        mime="text/csv",
    )


# -------------------------------------------------
# BLIND SPOT HUNTER
# -------------------------------------------------

st.divider()
st.header("Blind Spot Hunter")

st.write(
    "Discover which machine locations are hardest to monitor "
    "using the current sensor configuration."
)

if st.button("Analyze Blind Spots", type="primary"):

    with st.spinner("Analyzing simulated fault locations..."):

        if "optimization_result" in st.session_state:
            active_config = st.session_state[
                "optimization_result"
            ]["best_config"]
        else:
            active_config = BASELINE

        analysis = evaluate_configuration(
            active_config,
            scenario_set="validation",
            seed=int(seed),
        )

        st.session_state["blind_spot_analysis"] = analysis
        st.session_state["blind_spot_config"] = active_config

if "blind_spot_analysis" in st.session_state:

    analysis = st.session_state["blind_spot_analysis"]
    active_config = st.session_state["blind_spot_config"]

    rows = []

    for position in range(8):

        scenarios = [
            item
            for item in analysis["scenario_results"]
            if item["fault_position"] == position
            and item["fault_type"] != "healthy"
        ]

        detected = sum(
            1 for item in scenarios if item["detected"]
        )

        delays = [
            item["detection_delay_s"]
            for item in scenarios
            if item["detection_delay_s"] is not None
        ]

        avg_delay = (
            sum(delays) / len(delays)
            if delays else None
        )

        recall = (
            detected / len(scenarios)
            if scenarios else 0
        )

        rows.append({
            "Position": position,
            "Sensor Installed": (
                position in active_config["sensor_positions"]
            ),
            "Fault Recall": recall,
            "Average Detection Delay (s)": avg_delay,
        })

    blind_df = pd.DataFrame(rows)

    st.subheader("Machine Monitoring Map")

    st.write(
        "Each bar represents a possible sensor location. "
        "Longer detection delays indicate weaker monitoring."
    )

    chart = px.bar(
        blind_df,
        x="Position",
        y="Average Detection Delay (s)",
        color="Sensor Installed",
        title="Detection Delay by Fault Location",
        labels={
            "Position": "Machine Position",
            "Average Detection Delay (s)":
                "Average Detection Delay (seconds)",
        },
    )

    st.plotly_chart(chart, width="stretch")

    st.subheader("Location Analysis")

    st.dataframe(
        blind_df,
        width="stretch",
        hide_index=True,
    )

    slowest = blind_df.sort_values(
        "Average Detection Delay (s)",
        ascending=False,
        na_position="first",
    ).iloc[0]

    st.warning(
        f"Potential blind spot: Position "
        f"{int(slowest['Position'])}. "
        "This location has the weakest observed "
        "detection performance in the tested scenarios."
    )

    st.caption(
        "Blind spots are estimated from simplified simulated "
        "fault scenarios. A long detection delay is not the "
        "same as a completely missed fault."
    )
